import * as argon2 from 'argon2';

async function registerUser(password: string): Promise<string> {
  try {
    const hash = await argon2.hash(password, {
      type: argon2.argon2id,
      memoryCost: 2 ** 16, // 64 MiB
      timeCost: 3,
      parallelism: 1,
    });
    return hash;
  } catch (err) {
    throw new Error(`Password hashing failed: ${err}`);
  }
}

import * as argon2 from 'argon2';

async function loginUser(submittedPassword: string, storedHash: string): Promise<boolean> {
  try {
    return await argon2.verify(storedHash, submittedPassword);
  } catch (err) {
    return false;
  }
}
